<html lang="en">
<head>
 <meta charset="UTF-8" />
 <meta name="viewport" content="width=device-width, initial-scale=1.0" />
 <title>VAPI Admin Checklist</title>
 <style>
 body {
 font-family: Arial, sans-serif;
 color: #111;
 margin: 0;
 padding: 24px;
 background: #f4f4f4;
 }
 .page {
 width: 210mm;
 min-height: 297mm;
