 content: "☐";
 position: absolute;
 left: 0;
 top: 0;
 color: #0f4c81;
 font-size: 14px;
 }
 .note {
 font-size: 12px;
 color: #555;
 margin-top: 6px;
 }
 .code {
 background: #f9f9f9;
 border: 1px solid #e0e0e0;
 padding: 8px 10px;
 display: inline-block;
 border-radius: 4px;
 font-family: Consolas, monospace;
 font-size: 12px;
 color: #333;
 }
 .box {
 border: 1px solid #ddd;
 background: #fcfcfc;
 padding: 16px;
 border-radius: 8px;
 margin: 12px 0;
 }
 .payload {
 font-family: Consolas, monospace;
 font-size: 12px;
 background: #f9f9fb;
 border: 1px solid #ddd;
 padding: 12px;
 border-radius: 6px;
 overflow-x: auto;
 margin-top: 10px;
 }
 .footer {
 margin-top: 18px;
 font-size: 12px;
 color: #666;
 }
