+import { useEffect } from 'react';
+
+export default function HubspotLeadForm() {
+ useEffect(() => {
+ const scriptId = 'hs-form-script';
+ const PORTAL_ID = import.meta.env.VITE_HUBSPOT_PORTAL_ID || '244236573';
